#!/usr/bin/env node
/**
 * Claude Code hooks for this repo, generated by the kura-hooks-setup skill from the Kura hooks.
 * Only the hooks the user chose are wired in .claude/settings.json, CONFIG below holds this repo's values.
 *   node .claude/hooks/repo-hooks.mjs start      SessionStart: optional style skill + short briefing
 *   node .claude/hooks/repo-hooks.mjs pre-tool   PreToolUse: repo search through lady-lens, no blocked command
 *   node .claude/hooks/repo-hooks.mjs post-edit  PostToolUse (Edit/Write): lady-lens sync in the background
 *   node .claude/hooks/repo-hooks.mjs prompt     UserPromptSubmit: the user's request to the inbox file
 *   node .claude/hooks/repo-hooks.mjs stop       Stop: status file updated today when files changed
 *   node .claude/hooks/repo-hooks.mjs snapshot   PreCompact / SessionEnd: git facts into the status file
 *   node .claude/hooks/repo-hooks.mjs selftest   checks the CONFIG against a few sample calls
 * Exit 2 = blocked, stderr goes to the model.
 */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn, spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

// ---- CONFIG: filled in per repo by kura-hooks-setup (keep keys of hooks that are off, they are just unused) ----
const CONFIG = {
    // pre-tool / post-edit (lady-lens)
    lensGuard: true,
    repoDirs: ['src', 'test', 'docs'],             // top-level folders lens indexes
    repoFiles: ['package.json', 'README.md'],      // top-level files lens indexes
    notIndexed: ['node_modules', '.git', 'dist'],  // shell search is fine here (build output, logs, scratch)
    lensPort: 4318,
    // pre-tool: shell commands the agent may not run, each with what to do instead ([] = none)
    blockedCommands: [
        { pattern: '(?:^|[;&|]\\s*)npm\\s+(?:run\\s+)?test(?=\\s|$|;|&|\\|)', message: 'Run the tests with the quiet command: npm run test:quiet.' },
        { pattern: '\\bgit\\s+push\\b', message: 'Never git push: the owner pushes.' }
    ],
    // start
    styleSkill: '${CLAUDE_PLUGIN_ROOT}/skills/kura-caveman/SKILL.md', // concise token-efficient communication
    briefingCommand: null,                         // e.g. ['npm', 'run', 'session:init'], null = built-in briefing
    // prompt / stop / snapshot
    owner: 'the user',
    inboxFile: 'backlog/inbox.md',
    statusFile: 'backlog/now.md',
    updatedMarker: 'Updated:',
    // The inbox is for structural discussions that must not get lost, not for quick questions or commands.
    inboxMinWords: 12,                             // shorter messages (also short questions) are no inbox item
    inboxIgnore: [                                 // whole-message replies, ignored at any length, add the user's own language
        'yes', 'no', 'ok', 'okay', 'sure', 'go', 'go ahead', 'go on', 'continue', 'proceed', 'next', 'do it', 'do that',
        'thanks', 'thank you', 'great', 'perfect', 'looks good', 'lgtm', 'agreed', 'correct', 'right', 'fine',
        'commit', 'commit it', 'push', 'commit and push', 'run the tests', 'try again', 'retry', 'fix it', 'undo', 'stop', 'cancel'
    ]
};
// ---- end CONFIG ----

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const posix = (value) => String(value ?? '').replace(/\\/g, '/');
const escape = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const today = () => new Date().toISOString().slice(0, 10);
const expandEnv = (str) => String(str ?? '')
    .replace(/^~/, os.homedir())
    .replace(/\$\{([^}]+)\}/g, (_, k) => process.env[k] ?? '')
    .replace(/%([^%]+)%/g, (_, k) => process.env[k] ?? '');
const inRoot = (...parts) => path.join(ROOT, ...parts);
const read = (file) => (fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '');
const git = (...args) => (spawnSync('git', args, { cwd: ROOT, windowsHide: true, encoding: 'utf8' }).stdout ?? '').trim();

const NOT_INDEXED = new RegExp(`(?:^|/)(?:${CONFIG.notIndexed.map(escape).join('|')})(?:/|$)|scratchpad|/Temp/|/tmp/`, 'i');
// A search command at the start of a pipeline segment, not a word inside a script or a string.
const SHELL_SEARCH = /^\s*\(?\s*(?:grep|egrep|rg|find|cat|head|tail|sed\s+-n|Select-String|Get-Content|gc|sls)\b/;
const REPO_PATH = new RegExp(
    `(?:^|[\\s'"=(])(?:\\./)?(?:${CONFIG.repoDirs.map(escape).join('|')})/|(?:^|\\s)(?:\\.|\\./)(?:\\s|$)` +
    (CONFIG.repoFiles.length ? `|\\b(?:${CONFIG.repoFiles.map(escape).join('|')})\\b` : ''));
const LENS = `Use lady-lens for search in this repo: searchView, grep, glob, read_chunk (mcp__lady-lens__*). Shell search only in ${CONFIG.notIndexed.join(', ')} or the scratchpad.`;

/** A reason to block a search tool call, or null. Grep/Glob without a not-indexed path search the repo. */
export function lensViolation(toolName, input = {}) {
    if (!CONFIG.lensGuard) return null;
    if (toolName === 'Grep' || toolName === 'Glob') {
        const where = posix(input.path ?? '');
        const insideRepo = !where || !path.isAbsolute(where) || posix(path.resolve(where)).toLowerCase().startsWith(posix(ROOT).toLowerCase());
        return insideRepo && !NOT_INDEXED.test(where) && !NOT_INDEXED.test(posix(input.pattern ?? '')) ? LENS : null;
    }
    if (toolName === 'Bash' || toolName === 'PowerShell') {
        // Per pipeline segment: filtering another command's output (`git log | grep x`) is no search in the repo.
        const segments = posix(input.command ?? '').split(/\|\||&&|[|;&\n]/);
        return segments.some(s => SHELL_SEARCH.test(s) && REPO_PATH.test(s) && !NOT_INDEXED.test(s)) ? LENS : null;
    }
    return null;
}

/** The message of the first blocked command the shell command matches, or null. */
export function blockedCommand(toolName, input = {}) {
    if (toolName !== 'Bash' && toolName !== 'PowerShell') return null;
    return CONFIG.blockedCommands.find(rule => new RegExp(rule.pattern).test(String(input.command ?? '')))?.message ?? null;
}

const IGNORED = new RegExp(`^(?:${CONFIG.inboxIgnore.map(escape).join('|')})[\\s.!?]*$`, 'i');

/** The user's message as an inbox line, or null for a short message, an ignored reply, a slash command or a system message. */
export function inboxEntry(prompt, now = new Date()) {
    const text = String(prompt ?? '').replace(/\s+/g, ' ').trim();
    if (!text || text.startsWith('/') || /^<[a-z][\w-]*[\s>]/i.test(text) || IGNORED.test(text) || text.split(' ').length < CONFIG.inboxMinWords) return null;
    const stamp = `${now.toISOString().slice(0, 10)} ${now.toTimeString().slice(0, 5)}`;
    return `- [ ] ${stamp} ${text.length > 300 ? `${text.slice(0, 300)} ...` : text}`;
}

const SNAPSHOT_START = '<!-- auto-snapshot: written by a hook before a context compaction or at session end; replaced each time -->';

/** The status file with its snapshot block replaced (or added at the end), the agent's own text above it stays. */
export function withSnapshot(note, snapshot) {
    const own = String(note ?? '').split(SNAPSHOT_START)[0].trimEnd();
    return `${own}\n\n${SNAPSHOT_START}\n## Snapshot (automatic)\n${snapshot.trim()}\n`;
}

const readStdin = () => { try { return JSON.parse(fs.readFileSync(0, 'utf8') || '{}'); } catch { return {}; } };

const HOOKS = {
    start: () => {
        const style = CONFIG.styleSkill && expandEnv(CONFIG.styleSkill);
        if (style && fs.existsSync(style)) console.log(read(style).replace(/^---[\s\S]*?---\s*/, ''));
        if (CONFIG.briefingCommand) {
            const [cmd, ...args] = CONFIG.briefingCommand;
            spawnSync(cmd, args, { cwd: ROOT, windowsHide: true, stdio: 'inherit', shell: process.platform === 'win32' });
            return;
        }
        const open = read(inRoot(CONFIG.inboxFile)).split(/\r?\n/).filter(line => line.startsWith('- [ ]'));
        console.log([
            `Branch: ${git('rev-parse', '--abbrev-ref', 'HEAD')} | last commit: ${git('log', '--oneline', '-1')}`,
            `Uncommitted: ${git('status', '--porcelain').split(/\r?\n/).filter(Boolean).length} file(s)`,
            open.length ? `Open in ${CONFIG.inboxFile}:\n${open.slice(-10).join('\n')}` : '',
            read(inRoot(CONFIG.statusFile)).split(SNAPSHOT_START)[0].trim().slice(0, 2000)
        ].filter(Boolean).join('\n'));
    },
    'pre-tool': () => {
        const { tool_name: toolName, tool_input: input } = readStdin();
        const reason = lensViolation(toolName, input) ?? blockedCommand(toolName, input);
        if (reason) { console.error(reason); process.exit(2); }
    },
    'post-edit': () => {
        const file = posix(readStdin().tool_input?.file_path ?? '');
        if (!file.toLowerCase().startsWith(posix(ROOT).toLowerCase())) return;
        // A running lens daemon syncs in its own process, only a refused connection means no daemon (a timeout is a busy one).
        fetch(`http://127.0.0.1:${CONFIG.lensPort}/sync?repo=${encodeURIComponent(ROOT)}`, { method: 'POST', signal: AbortSignal.timeout(4000) })
            .catch(error => error?.cause?.code === 'ECONNREFUSED'
                && spawn('lens', ['sync'], { cwd: ROOT, windowsHide: true, stdio: 'ignore', shell: process.platform === 'win32' }).unref());
    },
    prompt: () => {
        const entry = inboxEntry(readStdin().prompt);
        if (!entry) return;
        const inbox = inRoot(CONFIG.inboxFile);
        fs.mkdirSync(path.dirname(inbox), { recursive: true });
        if (!fs.existsSync(inbox)) fs.writeFileSync(inbox, `# Inbox: questions and requests of ${CONFIG.owner}\n\nOpen = \`- [ ]\`; answered = \`- [x] ... -> answer or pointer\`.\n\n`);
        fs.appendFileSync(inbox, `${entry}\n`);
    },
    snapshot: () => {
        const event = readStdin().hook_event_name ?? 'snapshot';
        const file = inRoot(CONFIG.statusFile);
        const snapshot = [
            `- ${today()} ${new Date().toTimeString().slice(0, 5)} (${event})`,
            `- branch and last commit: ${git('rev-parse', '--abbrev-ref', 'HEAD')} ${git('log', '--oneline', '-1')}`,
            `- changed, not committed: ${git('status', '--porcelain').split(/\r?\n/).filter(Boolean).join('; ') || 'nothing'}`
        ].join('\n');
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, withSnapshot(read(file) || '# Now\n', snapshot));
    },
    stop: () => {
        if (readStdin().stop_hook_active) return;
        const changed = git('status', '--porcelain');
        if (changed && !read(inRoot(CONFIG.statusFile)).includes(`${CONFIG.updatedMarker} ${today()}`)) {
            console.error(`Files changed but ${CONFIG.statusFile} is not updated today: write the task, the last step, the next step and what is not verified (line "${CONFIG.updatedMarker} ${today()}")${CONFIG.inboxFile ? `, and tick off answered items in ${CONFIG.inboxFile}` : ''}.`);
            process.exit(2);
        }
    },
    selftest: () => {
        if (CONFIG.lensGuard) {
            assert.ok(lensViolation('Grep', { pattern: 'x' }), 'Grep in the repo is blocked');
            assert.ok(lensViolation('Bash', { command: `grep -rn foo ${CONFIG.repoDirs[0]}/` }), 'shell grep on a repo folder is blocked');
            assert.equal(lensViolation('Bash', { command: 'git log --oneline | grep fix' }), null, 'filtering command output is allowed');
            assert.equal(lensViolation('Grep', { pattern: 'x', path: CONFIG.notIndexed[0] }), null, 'not-indexed folders are allowed');
        }
        for (const rule of CONFIG.blockedCommands) {
            assert.ok(rule.pattern && rule.message, 'every blocked command has a pattern and a message');
            assert.ok(!new RegExp(rule.pattern).test(rule.message.replace(/^[^:]*:\s*/, '')), `the advice of ${rule.pattern} is not blocked itself`);
        }
        assert.equal(blockedCommand('Bash', { command: 'git status' }), null, 'an ordinary command is allowed');
        if (CONFIG.blockedCommands.some(r => /git/.test(r.pattern))) assert.ok(blockedCommand('Bash', { command: 'git push origin main' }), 'MUST block: git push');
        assert.equal(inboxEntry(CONFIG.inboxIgnore[0]), null, 'an ignored reply is no inbox item');
        assert.equal(inboxEntry('Why does the build fail?'), null, 'a short question is no inbox item');
        const long = 'Should the order service own the pricing rules, or do we move them to a separate pricing module that both use?';
        assert.match(inboxEntry(long) ?? '', /^- \[ \] \d{4}-\d\d-\d\d/, 'a structural discussion goes in the inbox');
        assert.equal(withSnapshot(withSnapshot('# Now\nown text', 'a'), 'b').split(SNAPSHOT_START).length, 2, 'one snapshot block');
        console.log('selftest ok');
    }
};

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) HOOKS[process.argv[2]]?.();
